window.UP_CONTENT = window.UP_CONTENT || {};
(window.UP_CONTENT.facts = window.UP_CONTENT.facts || []).push(
  // ---------------- SPACE ----------------
  { id: "sp19", topic: "space", headline: "Halley's Comet swings past Earth about once every 76 years", body: "Halley's Comet loops out beyond Neptune and back on a roughly 76-year orbit, so most people get one chance to see it. It last appeared in 1986 and is due back in 2061.", q: "About how often does Halley's Comet return to Earth's skies?", options: ["About every 7 years","About every 76 years","About every 100 years","About every 300 years"], a: 1, explain: "Mark Twain was born during its 1835 visit, predicted he'd 'go out with it', and died the day after it passed closest to the Sun in 1910.", tip: "" },
  { id: "sp20", topic: "space", headline: "Mars's moon Phobos is slowly spiralling in toward the planet", body: "Phobos orbits only about 6,000 km above Mars and creeps closer by roughly 1.8 m every century. In tens of millions of years it should crash into Mars or be torn apart into a ring.", q: "What is the long-term fate of Phobos, the larger moon of Mars?", options: ["Drift away and escape into space","Crash into Mars or become a ring","Collide with Mars's other moon, Deimos","Be pulled away by Jupiter's gravity"], a: 1, explain: "Phobos circles faster than Mars spins, so from the ground it rises in the west and sets in the east, twice a day.", tip: "" },
  { id: "sp21", topic: "space", legendary: true, headline: "Neptune was found with maths before anyone knew where to look", body: "Uranus kept drifting off its predicted path. Urbain Le Verrier calculated that an unseen planet must be tugging on it, and in 1846 Johann Galle found Neptune within about 1° of his predicted spot.", q: "How was the planet Neptune first discovered in 1846?", options: ["Seen first by an amateur stargazer","Spotted by chance in a comet search","Predicted by maths, then spotted","Recorded on ancient Babylonian charts"], a: 2, explain: "Galileo had sketched Neptune in his notes in 1612–13 but took it for a star, missing the discovery by over 200 years.", tip: "" },
  { id: "sp22", topic: "space", headline: "A canyon on Mars would stretch across the entire United States", body: "Valles Marineris runs about 4,000 km along Mars's equator and plunges up to about 7 km deep. It formed mostly as the crust cracked and pulled apart, not by a river carving it.", q: "Roughly how long is Valles Marineris, the giant canyon system on Mars?", options: ["About 40 km","About 400 km","About 4,000 km","About 40,000 km"], a: 2, explain: "Earth's Grand Canyon is about 450 km long, so Valles Marineris is nearly ten times longer.", tip: "" },
  { id: "sp23", topic: "space", headline: "Most shooting stars are space dust no bigger than a grain of sand", body: "A meteor's bright streak comes from a tiny particle hitting the upper atmosphere at tens of kilometres per second. The air around it heats until it glows, and the grain burns up far above the ground.", q: "What usually causes a typical 'shooting star'?", options: ["A tiny grain burning up in the air","A distant star collapsing or dying","Old satellites falling back to Earth","Lightning flashes in the upper sky"], a: 0, explain: "Meteor showers happen when Earth ploughs through dust left by a comet; the Perseids come from Comet Swift–Tuttle.", tip: "For the Perseids around 12 August, watch after midnight from a dark spot and give your eyes 20 minutes to adjust." },
  { id: "sp24", topic: "space", headline: "The Voyager probes carry a golden record of life on Earth", body: "Launched in 1977, Voyager 1 and 2 each carry a gold-plated copper record with greetings in 55 languages, natural sounds, and music from Bach to Chuck Berry's 'Johnny B. Goode'.", q: "What message did NASA attach to both Voyager probes launched in 1977?", options: ["A plaque listing every US state","A golden record of Earth sounds","A sealed jar of soil and seeds","A radio beacon broadcasting news"], a: 1, explain: "Each record came with a stylus and diagrams on its cover explaining how to play it, in case anyone ever finds one.", tip: "NASA has put the Golden Record's sounds and images online, so you can hear what we sent to the stars." },
  { id: "sp25", topic: "space", headline: "The Moon's dark 'seas' are ancient lava plains with no water", body: "Early astronomers thought the dark patches on the Moon were oceans and named them maria, Latin for seas. They are actually vast plains of hardened lava that flooded giant basins billions of years ago.", q: "What are the dark patches on the Moon known as 'seas' (maria) made of?", options: ["Frozen water ice","Dried-up ocean beds","Hardened ancient lava","Dark dust blown by wind"], a: 2, explain: "Apollo 11 landed in one of them in 1969: Mare Tranquillitatis, the Sea of Tranquillity.", tip: "" },
  { id: "sp26", topic: "space", headline: "Stars twinkle but planets mostly don't: a quick way to tell them apart", body: "Stars are so far away they act as single points of light, which turbulent air easily bends back and forth. Planets show a tiny disc, so the wobbles average out and they shine more steadily.", q: "Why do planets usually twinkle less than stars in the night sky?", options: ["They shine with their own steady light","They sit outside Earth's atmosphere","They move too fast to visibly flicker","They look like discs, not points"], a: 3, explain: "Space telescopes like Hubble sit above the atmosphere, where stars don't twinkle at all.", tip: "Spot a bright 'star' that shines steadily without twinkling? It's probably Venus, Jupiter, Mars or Saturn." },
  { id: "sp27", topic: "space", headline: "Seen from space, the Sun is white, not yellow", body: "The Sun gives off light across all visible colours, which blend into white. Our atmosphere scatters away some blue light, so from the ground it looks yellowish, and orange or red near the horizon.", q: "What colour does the Sun appear to astronauts in space?", options: ["Plain white","Pale yellow","Deep orange","Pale green"], a: 0, explain: "The Sun's output actually peaks around blue-green light, but our eyes combine all its colours into white.", tip: "Never look straight at the Sun, even when partly eclipsed; use certified solar eclipse glasses." },
  { id: "sp28", topic: "space", headline: "Mercury and Venus are the only planets with no moons at all", body: "Every other planet has at least one moon: Earth has one, Mars has two and the giant planets have dozens each. Mercury and Venus, the two closest to the Sun, have none.", q: "Which two planets in our solar system have no moons?", options: ["Mars and Mercury","Mercury and Venus","Venus and Uranus","Earth and Mars"], a: 1, explain: "So close to the Sun, its strong gravity would likely pull a moon away or make its orbit unstable.", tip: "" },
  // ---------------- SCIENCE ----------------
  { id: "sc19", topic: "science", headline: "Bananas are very slightly radioactive", body: "Bananas are rich in potassium, and a tiny fraction of all natural potassium is the radioactive form potassium-40. The dose from eating one is minuscule, far less than a day's natural background radiation.", q: "Why are bananas very slightly radioactive?", options: ["They absorb radon from soil","They're treated with radiation","They contain potassium-40","They contain uranium traces"], a: 2, explain: "Your own body holds far more potassium-40 than a banana does, so you are mildly radioactive too.", tip: "" },
  { id: "sc20", topic: "science", headline: "Helium doesn't raise your voice's pitch; it changes its tone", body: "Your vocal cords vibrate at the same rate in helium. But sound travels nearly three times faster in helium than in air, which shifts the resonances of your throat and mouth, making voices sound squeaky.", q: "Why does breathing helium make a voice sound squeaky?", options: ["It tightens the vocal cords","It shrinks the lungs","It speeds up the vocal cords","Sound moves faster in it"], a: 3, explain: "The heavy gas sulfur hexafluoride does the opposite, making voices sound deep, because sound travels slowly in it.", tip: "" },
  { id: "sc21", topic: "science", legendary: true, headline: "Water can boil and freeze at the same time", body: "At its 'triple point', about 0.01 °C and roughly 0.6% of normal air pressure, water exists as solid, liquid and vapour all at once. In a vacuum chamber you can watch it boil and freeze together.", q: "In physics, what is water's 'triple point'?", options: ["Where ice, water and vapour coexist","The temperature where water is densest","The point where salt water freezes","Boiling point at the top of Everest"], a: 0, explain: "It's so precise and repeatable that for decades it was used to define the kelvin temperature scale.", tip: "" },
  { id: "sc22", topic: "science", headline: "Tonic water glows blue under ultraviolet light", body: "Tonic water contains quinine, a molecule that absorbs invisible ultraviolet light and re-emits it as visible blue light. Under a blacklight, a glass of gin and tonic glows an eerie blue.", q: "What ingredient makes tonic water glow under a blacklight?", options: ["Sugar","Quinine","Carbonation","Citric acid"], a: 1, explain: "Quinine, from the bark of the cinchona tree, was long used to treat malaria; tonic water contains much less today.", tip: "" },
  { id: "sc23", topic: "science", headline: "Cloudy ice comes from trapped gas and impurities, not dirty water", body: "Ice in a tray freezes from the outside in, pushing dissolved air and minerals toward the centre, where they get trapped as a white cloud. Ice frozen slowly from one direction comes out clear.", q: "What usually makes homemade ice cubes cloudy in the middle?", options: ["Bacteria in the water","Freezer frost","Trapped air and minerals","Water freezing too slowly"], a: 2, explain: "Lake ice is often clear for the same reason: it freezes slowly from the top down.", tip: "For clear ice, freeze water in a small insulated cooler with the lid off, then cut away the cloudy bottom." },
  { id: "sc24", topic: "science", headline: "The sky looks blue, not violet, partly because of our eyes", body: "Air scatters short wavelengths most, and violet is shorter than blue. But sunlight contains less violet to begin with, and our eyes are much less sensitive to it, so the sky looks blue to us.", q: "Air scatters violet light even more than blue, so why does the sky look blue?", options: ["The oceans reflect blue light upward","Ozone filters out the violet light","Violet light can't reach Earth's surface","Less violet sunlight; eyes favour blue"], a: 3, explain: "The scattering is named after Lord Rayleigh, who worked out in the 1870s why it favours shorter wavelengths.", tip: "" },
  { id: "sc25", topic: "science", headline: "Static shocks get worse in winter because dry air lets charge build", body: "Moisture in the air normally helps electric charge leak away from your body. In dry winter air, walking on carpet can build up thousands of volts, released as a snap when you touch metal.", q: "Why are static electric shocks more common in winter?", options: ["Dry air lets charge build up","Cold makes skin conduct better","Heaters create electricity","Winter clothes are magnetic"], a: 0, explain: "The shock carries thousands of volts but only a tiny current for a split second, so it stings without harm.", tip: "Touch metal with a key or coin first; the spark jumps from the metal, not your fingertip." },
  { id: "sc26", topic: "science", headline: "Copper surfaces kill many germs that land on them", body: "Copper releases ions that damage the membranes of bacteria and viruses. In 2008 the US EPA registered copper alloys as antimicrobial after tests showed they killed over 99.9% of certain bacteria within two hours.", q: "Why do copper surfaces reduce germs on them?", options: ["Copper stays too cold for germs","Copper ions damage microbes","Copper's slick surface repels water","Copper's magnetic field disrupts cells"], a: 1, explain: "Brass and bronze are copper alloys too, which is why they were included in the EPA's registration.", tip: "" },
  { id: "sc27", topic: "science", headline: "Water drops skate on a very hot pan instead of boiling away", body: "On a pan well above boiling, around 200 °C, a water drop instantly forms a cushion of vapour beneath it and glides around for a while. This is the Leidenfrost effect, and it insulates the drop from the heat.", q: "What causes water drops to skate across a very hot pan?", options: ["Leftover oil on the pan's surface","Static charge repelling the drops","A cushion of vapour beneath them","Surface tension making them bounce"], a: 2, explain: "The effect is named after Johann Leidenfrost, a German doctor who described it in 1756.", tip: "Heating a stainless pan? When a drop of water beads up and glides around, it's hot enough to add oil." },
  { id: "sc28", topic: "science", headline: "In space, candle flames burn as round blue balls", body: "On Earth, hot gas from a flame rises and cooler air rushes in below, stretching it into a teardrop. In microgravity there's no rising, so flames become spheres, often dim and blue.", q: "What shape does a candle flame take in microgravity?", options: ["A long thin spike","The usual teardrop","A flat ring","A round ball"], a: 3, explain: "NASA studies flames on the International Space Station to understand combustion and improve fire safety.", tip: "" },
  // ---------------- EARTH ----------------
  { id: "ea19", topic: "earth", headline: "Lightning strikes the Empire State Building about 20 times a year", body: "Tall, pointed structures are prime lightning targets. The Empire State Building in New York is hit around 20 times a year on average, safely channelled into the ground by its lightning protection.", q: "Roughly how often is the Empire State Building struck by lightning?", options: ["Roughly once a century","About once a decade","About twice a year","About 20 times a year"], a: 3, explain: "A single lightning flash can contain several strokes along the same channel, which makes the flicker you see.", tip: "" },
  { id: "ea20", topic: "earth", headline: "Every 3 seconds between flash and thunder means about 1 km", body: "Light reaches you almost instantly, but sound travels about 1 km every 3 seconds. Count the seconds from flash to rumble and divide by 3 to estimate the storm's distance in kilometres.", q: "How do you estimate a storm's distance from lightning and thunder?", options: ["Multiply the seconds by 10 for km","Divide the seconds by 3 for km","Count seconds: each is 1 km","Divide the seconds by 20 for km"], a: 1, explain: "For miles, divide by 5 instead. Thunder is rarely heard more than about 15 km away.", tip: "If you can hear thunder, you're close enough to be struck. Go indoors and wait 30 minutes after the last rumble." },
  { id: "ea21", topic: "earth", headline: "Lightning hitting sand can fuse it into tubes of glass", body: "A bolt striking sandy soil can heat it to well over 1,700 °C in a split second, melting grains into hollow, branching glass tubes called fulgurites. Some trace the lightning's path for metres.", q: "What are the rare natural objects called fulgurites?", options: ["Rocks blasted out of erupting volcanoes","Crystals that grow slowly in caves","Glass tubes made by lightning in sand","Meteorites fused by hitting deserts"], a: 2, explain: "Their name comes from the Latin 'fulgur', meaning lightning.", tip: "" },
  { id: "ea22", topic: "earth", headline: "An Australian lake is bright pink, even in a glass", body: "Lake Hillier on Middle Island, Western Australia, is bubblegum pink. Its very salty water hosts salt-loving algae and microbes that produce reddish pigments, and the colour stays even when scooped up.", q: "What makes Australia's Lake Hillier bright pink?", options: ["Pink quartz sand lining its bed","Red minerals from a volcano","Reflection of sunset light","Salt-loving algae and microbes"], a: 3, explain: "The alga Dunaliella salina, one likely source, makes beta-carotene, the same pigment that colours carrots orange.", tip: "" },
  { id: "ea23", topic: "earth", legendary: true, headline: "Ancient corals show a year once had about 400 days", body: "Corals lay down daily growth bands. Fossil corals about 400 million years old show roughly 400 bands per year, so days were only about 22 hours long. Earth's spin has been slowly braking ever since.", q: "About how many days were in a year roughly 400 million years ago?", options: ["About 200","About 300","About 365","About 400"], a: 3, explain: "The brake is the Moon: tidal friction steadily drains Earth's spin, lengthening the day by about 2 milliseconds a century.", tip: "" },
  { id: "ea24", topic: "earth", headline: "Half of all the air on Earth lies below about 5.5 km", body: "Air is squeezed by the weight of the air above it, so it is densest near the ground. About half the atmosphere's mass sits below 5.5 km, lower than the summit of Kilimanjaro.", q: "Below about what altitude does half the mass of Earth's atmosphere lie?", options: ["About 500 m","About 5.5 km","About 50 km","About 100 km"], a: 1, explain: "On top of Everest, air pressure is only about a third of sea level, so each breath holds far less oxygen.", tip: "At high altitude, go slowly: above 3,000 m, raise your sleeping height by no more than about 500 m a day." },
  { id: "ea25", topic: "earth", headline: "The 'water' on a hot road is a mirage of the sky", body: "On hot days, air just above the road is much warmer than the air higher up. Light from the sky bends upward as it passes through, so you see a shimmering image of the sky that looks like a puddle.", q: "What are you seeing in the 'puddle' that appears on a hot road?", options: ["Evaporated oil","Real water vapour","A bent image of the sky","A heat-induced eye illusion"], a: 2, explain: "Mirages are real optical images, not hallucinations, so they can be photographed.", tip: "" },
  { id: "ea26", topic: "earth", headline: "A magnitude 7 quake releases about 1,000 times more energy than a 5", body: "Earthquake magnitude is logarithmic. Each step up means about 10 times more ground shaking and roughly 32 times more energy, so two steps is about a thousandfold jump in energy.", q: "About how much more energy does a magnitude 7 earthquake release than a magnitude 5?", options: ["About 20 times","About 100 times","About 1,000 times","About 10,000 times"], a: 2, explain: "Scientists now mostly use the 'moment magnitude' scale, which replaced Richter's original for large quakes.", tip: "" },
  { id: "ea27", topic: "earth", headline: "Green auroras come from oxygen about 100 to 250 km up", body: "Auroras glow when charged particles from the Sun crash into our upper atmosphere. Oxygen emits the common green light, and red at higher altitudes, while nitrogen adds blue and purple tints.", q: "Which gas produces the common green light in auroras?", options: ["Oxygen","Neon","Hydrogen","Nitrogen"], a: 0, explain: "Auroras happen near both poles at once; the southern version is called the aurora australis.", tip: "In faint auroras, your phone's night mode often captures colours your eyes can barely see." },
  { id: "ea28", topic: "earth", headline: "If the sea suddenly pulls back from the shore, a tsunami may follow", body: "Before some tsunamis arrive, the water drains far out, exposing the seabed. That's a natural warning. Tsunamis also come as a series of waves, and the first one is often not the largest.", q: "What should you do if the sea suddenly drains far back from the beach?", options: ["Walk out to look closer","Head to high ground at once","Wait for an official siren","Shelter on the beach in a car"], a: 1, explain: "Tsunami waves can keep arriving for hours, so stay away from the coast until officials say it's safe.", tip: "If you feel a strong or long quake at the coast, don't wait for an alert: move to high ground or inland." },
  // ---------------- NATURE ----------------
  { id: "na19", topic: "nature", headline: "Honeybees give directions with a waggle dance", body: "A forager returning to the hive performs a figure-of-eight dance. The angle of its waggling run shows the food's direction relative to the Sun, and the waggle's duration shows how far away it is.", q: "What does a honeybee's waggle dance tell other bees?", options: ["That the queen has died or left","Where a predator was last seen","Direction and distance to food","That the hive is too hot or full"], a: 2, explain: "Karl von Frisch decoded the dance and shared the 1973 Nobel Prize in Physiology or Medicine.", tip: "" },
  { id: "na20", topic: "nature", legendary: true, headline: "Sharks have existed longer than trees", body: "Fossil scales suggest shark relatives were swimming about 450 million years ago. The first true trees appeared roughly 385 million years ago, tens of millions of years later.", q: "Which appeared on Earth first: sharks or trees?", options: ["Trees, by tens of millions of years","Both appeared at about the same time","Sharks, by tens of millions of years","Both came only after the dinosaurs"], a: 2, explain: "Sharks also survived the asteroid impact that wiped out the non-bird dinosaurs 66 million years ago.", tip: "" },
  { id: "na21", topic: "nature", headline: "Owls can't move their eyes, so they turn their heads up to 270°", body: "An owl's eyes are tube-shaped and fixed in their sockets. To look around, owls rotate their heads up to about 270 degrees, helped by having 14 neck vertebrae, twice as many as humans.", q: "Why do owls swivel their heads so far around?", options: ["Their eyes can't move in sockets","To stretch their stiff neck muscles","To spot predators from behind","To hypnotise prey with the motion"], a: 0, explain: "Special blood vessel adaptations keep blood flowing to the brain even when the neck is twisted.", tip: "" },
  { id: "na22", topic: "nature", headline: "Botanically, bananas are berries but strawberries aren't", body: "To botanists, a berry is a fleshy fruit grown from a single flower ovary, usually with several seeds. Bananas, tomatoes and grapes qualify; strawberries don't, as their flesh grows from the flower's base.", q: "Which of these is a true berry in the botanical sense?", options: ["Strawberry","Banana","Raspberry","Cherry"], a: 1, explain: "Each 'seed' on a strawberry's surface is actually its own tiny fruit, called an achene.", tip: "" },
  { id: "na23", topic: "nature", headline: "Wood frogs freeze solid in winter and thaw back to life in spring", body: "In Alaska and Canada, wood frogs survive winter with much of their body water frozen. Their hearts and breathing stop, while high levels of glucose protect their cells until they thaw.", q: "How do North American wood frogs survive harsh winters?", options: ["They migrate south before the frost","They hibernate in unfrozen ponds","They grow a thick insulating skin","They freeze solid and later thaw"], a: 3, explain: "In Alaska, wood frogs have been found surviving months frozen at temperatures down to about −18 °C.", tip: "" },
  { id: "na24", topic: "nature", headline: "Hippos make their own red-tinted sunscreen", body: "Hippos ooze a fluid that starts clear and turns red, then brown. It isn't blood or sweat: its pigments absorb ultraviolet light and appear to slow the growth of bacteria.", q: "What does the reddish fluid that hippos secrete do?", options: ["Marks out their territory in rivers","Signals stress to the rest of the pod","Attracts mates during breeding season","Acts as sunscreen and antiseptic"], a: 3, explain: "Japanese researchers identified the two pigments in 2004, naming them hipposudoric and norhipposudoric acid.", tip: "" },
  { id: "na25", topic: "nature", headline: "Cats can't taste sweetness", body: "Cats carry a broken version of a gene needed for the sweet taste receptor. As strict meat-eaters, they lost little by losing it, and they show no preference for sugary foods.", q: "Why don't cats show interest in sugary food?", options: ["They lack a working sweet receptor","Sugar smells bitter and sour to them","Their tongues are too rough to taste it","Instinct teaches them sugar is toxic"], a: 0, explain: "Several other meat-eating mammals, such as sea lions and spotted hyenas, have also lost their sweet taste.", tip: "Despite the cliché, milk often upsets adult cats' stomachs, since many lose the ability to digest lactose." },
  { id: "na26", topic: "nature", headline: "Lyrebirds can mimic camera shutters and chainsaws", body: "Male superb lyrebirds in Australia weave the calls of dozens of other bird species into their songs. Some living near people have copied sounds like camera shutters, car alarms and chainsaws.", q: "What is the superb lyrebird of Australia famous for?", options: ["Building underground nests","Mimicking almost any sound","Flying backwards","Changing colour at will"], a: 1, explain: "Males perform their medleys while dancing on cleared mounds, with their huge tails fanned over their heads.", tip: "" },
  { id: "na27", topic: "nature", headline: "Ticks can't jump or fly: they wait on grass with arms outstretched", body: "Ticks find hosts by 'questing': climbing grass or shrubs and holding out their front legs, ready to grab anything that brushes past. They then crawl, often for a while, to find a spot to bite.", q: "How do ticks usually get onto people?", options: ["Jumping from the ground","Flying short distances","Grabbing on as we brush past","Being blown by the wind"], a: 2, explain: "Ticks detect breath, body heat and vibrations, and sense us using special organs on their front legs.", tip: "To remove a tick, grip it close to the skin with fine tweezers and pull straight up with steady pressure." },
  { id: "na28", topic: "nature", headline: "A honeybee's stinger keeps pumping venom after the bee is gone", body: "Honeybee stingers are barbed, so they lodge in our skin and tear away from the bee, which then dies. The attached venom sac can keep pumping, so the longer it stays in, the more venom you get.", q: "Why should a honeybee stinger be removed from the skin quickly?", options: ["It can lay eggs under the skin","It grows deeper over time","It attracts other bees","Its venom sac keeps pumping"], a: 3, explain: "A 1996 study found scraping versus pinching made no real difference; only the speed of removal mattered.", tip: "Stung by a honeybee? Get the stinger out right away any way you can; seconds matter more than method." },
  // ---------------- BODY ----------------
  { id: "bo19", topic: "body", headline: "You can't tickle yourself because your brain sees it coming", body: "When you move, your brain predicts what the touch will feel like and turns down the sensation. A tickle needs some surprise, so your own fingers barely register.", q: "Why is it almost impossible to tickle yourself?", options: ["Your brain predicts and dampens it","Your skin is numb to your own touch","Your fingers are too warm","You can't reach the right spots"], a: 0, explain: "In experiments, adding a short delay to a self-controlled tickling robot made people feel it more.", tip: "" },
  { id: "bo20", topic: "body", headline: "Pruney fingers in the bath are controlled by your nerves", body: "Wrinkled fingertips after a soak aren't just waterlogged skin. Nerves signal blood vessels to narrow, pulling the skin into folds. People with certain nerve damage don't wrinkle at all.", q: "What causes fingertips to wrinkle after a long soak?", options: ["Skin swelling as it absorbs water","Nerves narrowing blood vessels","Loss of body salt","Cold water shrinking bones"], a: 1, explain: "Doctors have used this water-immersion wrinkling as a simple test of nerve function in the hand.", tip: "" },
  { id: "bo21", topic: "body", headline: "Bright sunlight makes some people sneeze", body: "The photic sneeze reflex makes some people sneeze when they step into bright light. It runs in families and affects a sizeable minority of people, though exactly how it works is still unclear.", q: "What triggers the 'photic sneeze reflex'?", options: ["A sudden blast of cold air","Strong smells like pepper","Sudden bright light","Sudden loud noises"], a: 2, explain: "It's sometimes called ACHOO syndrome, a deliberately playful acronym coined by researchers.", tip: "" },
  { id: "bo22", topic: "body", legendary: true, headline: "Your brain itself can't feel pain", body: "Brain tissue has no pain receptors. That's why surgeons can operate on some patients while they are awake, asking them to talk so they can avoid harming areas for speech.", q: "Why can some brain surgery be done while the patient is awake?", options: ["The brain is numbed by its own fluid","Patients are hypnotised first","The skull blocks pain signals","Brain tissue has no pain receptors"], a: 3, explain: "Headaches come from the tissues around the brain, such as its membranes, blood vessels and muscles.", tip: "" },
  { id: "bo23", topic: "body", headline: "Your smallest bone is in your ear and is about 3 mm long", body: "The stapes, or stirrup, is one of three tiny bones in your middle ear that pass sound vibrations from the eardrum to the inner ear. It's roughly the size of a grain of rice.", q: "Where is the smallest bone in the human body?", options: ["In the middle ear","In the little toe","In the bridge of the nose","In the wrist"], a: 0, explain: "Its two neighbours, the malleus and incus, are nicknamed the hammer and anvil.", tip: "" },
  { id: "bo24", topic: "body", headline: "Much of what you call taste is actually smell", body: "Your tongue detects basics like sweet, salty, sour, bitter and umami. Rich flavours like strawberry or coffee come mostly from aromas reaching your nose from the back of your mouth as you chew.", q: "Why does food taste bland when you have a blocked nose?", options: ["Taste buds shut down when you're ill","Flavour relies heavily on smell","Mucus coats the tongue's taste buds","The brain switches off taste to rest"], a: 1, explain: "Smelling from inside the mouth is called retronasal smell, and your brain experiences it as 'taste'.", tip: "Try it: pinch your nose and eat a jelly bean, then let go. The flavour floods in all at once." },
  { id: "bo25", topic: "body", headline: "Brain freeze is a pain sent from the roof of your mouth", body: "When something icy touches the roof of your mouth, nearby blood vessels rapidly narrow and then widen. Nerves there report the change, and your brain feels it as a sharp pain in the forehead.", q: "Where does the 'brain freeze' from cold food actually begin?", options: ["Inside the brain itself","In the teeth","The roof of your mouth","In the back of the throat"], a: 2, explain: "Pain felt somewhere other than its source is called referred pain; heart attacks felt in the arm are another example.", tip: "Got brain freeze? Press your tongue against the roof of your mouth or sip something warm to ease it." },
  { id: "bo26", topic: "body", headline: "Your red blood cells have no nucleus and last about 120 days", body: "To make room for oxygen-carrying haemoglobin, red blood cells eject their nucleus as they mature. Without it they can't repair themselves, and each wears out after about four months.", q: "About how long does a human red blood cell typically live?", options: ["About 1 day","About 10 days","About 120 days","About 10 years"], a: 2, explain: "To keep up, your bone marrow makes about 2 million new red blood cells every second.", tip: "" },
  { id: "bo27", topic: "body", headline: "Motion sickness comes from your eyes and inner ear disagreeing", body: "Reading in a moving car, your eyes report stillness while your inner ear senses motion. This sensory mismatch is the leading explanation for the nausea of car, sea and air sickness.", q: "What is the main explanation for motion sickness?", options: ["Eyes and inner ear disagree","Low blood sugar from skipped meals","Stomach acid sloshing with motion","Too little oxygen in the vehicle"], a: 0, explain: "The inner ear's fluid-filled canals detect rotation, while tiny crystals inside it sense tilt and acceleration.", tip: "In a car, sit in front and look at the horizon; looking down at a screen or book usually makes it worse." },
  { id: "bo28", topic: "body", headline: "Identical twins have different fingerprints", body: "Identical twins share nearly identical DNA, but fingerprints form in the womb, shaped by things like each finger's position, pressure and growth. So even identical twins end up with different prints.", q: "Do identical twins have the same fingerprints?", options: ["Yes, exactly the same","No, their prints differ","Only on the thumbs","Only until puberty"], a: 1, explain: "Fingerprint ridges form during roughly the third and fourth months of pregnancy and stay for life.", tip: "" },
  // ---------------- HISTORY ----------------
  { id: "hi19", topic: "history", headline: "Napoleon wasn't short: he was about average height", body: "Napoleon stood about 1.69 m (5 ft 7 in), typical for a Frenchman of his time. The myth grew from French inches being longer than English ones, plus British cartoons mocking him as tiny.", q: "How tall was Napoleon Bonaparte compared with men of his era?", options: ["Unusually short","Unusually tall","About average","Just under 1.5 m"], a: 2, explain: "His nickname 'le petit caporal' (the little corporal) was a term of affection from his soldiers, not about height.", tip: "" },
  { id: "hi20", topic: "history", headline: "Vikings almost certainly didn't wear horned helmets", body: "No horned Viking-age helmet has ever been found. The image largely comes from 1870s costumes for Wagner's opera cycle 'The Ring of the Nibelung', which spread the look worldwide.", q: "Where does the image of Vikings in horned helmets mainly come from?", options: ["Helmets found in Viking graves","Descriptions in medieval Norse sagas","Roman reports of Norse warriors","19th-century opera costumes"], a: 3, explain: "The only nearly complete Viking-age helmet found, at Gjermundbu in Norway, is a simple rounded iron cap.", tip: "" },
  { id: "hi21", topic: "history", headline: "You can't see the Great Wall of China from the Moon", body: "The Great Wall is very long but only a few metres wide and similar in colour to the land around it. From the Moon it's invisible to the naked eye, and even from low orbit it's very hard to spot.", q: "Can the Great Wall of China be seen from the Moon with the naked eye?", options: ["No, it's far too narrow","Yes, it's clearly visible","Only at night","Only with the Sun low behind it"], a: 0, explain: "China's first astronaut, Yang Liwei, said in 2003 that he couldn't see it from orbit.", tip: "" },
  { id: "hi22", topic: "history", headline: "Cleopatra was the first of her dynasty to learn Egyptian", body: "Cleopatra VII belonged to the Ptolemies, a Greek-speaking dynasty founded by one of Alexander the Great's generals. According to Plutarch, she was the first of her line to bother learning Egyptian.", q: "What language was the native tongue of Cleopatra's royal family?", options: ["Egyptian","Greek","Latin","Persian"], a: 1, explain: "Plutarch also claimed she spoke many other languages and rarely needed an interpreter.", tip: "" },
  { id: "hi23", topic: "history", headline: "Marie Curie's notebooks are still too radioactive to handle freely", body: "Marie Curie's papers and notebooks are contaminated with radium, which has a half-life of about 1,600 years. In Paris they are kept in lead-lined boxes, and readers must sign a waiver to see them.", q: "Why are Marie Curie's notebooks stored in lead-lined boxes?", options: ["To stop them being stolen","To keep out moisture","They're still radioactive","To block magnetic fields"], a: 2, explain: "Curie won Nobel Prizes in both physics (1903) and chemistry (1911), the first person to win two.", tip: "" },
  { id: "hi24", topic: "history", headline: "Roman concrete could heal its own cracks", body: "Roman builders mixed concrete with quicklime, leaving small white lumps of lime inside. A 2023 MIT study found that when cracks let in water, these lumps react and refill the cracks with new mineral.", q: "What helped some ancient Roman concrete heal its own cracks?", options: ["Volcanic glass fibres","Animal blood mixed into the mortar","Iron rods set inside the concrete","Lumps of lime in the mix"], a: 3, explain: "Roman harbour walls even grew stronger in seawater, as new minerals crystallised inside them over time.", tip: "" },
  { id: "hi25", topic: "history", headline: "The Eiffel Tower was only meant to stand for 20 years", body: "Built for the 1889 World's Fair in Paris, the tower had a permit for 20 years, after which it could be taken down. It was saved largely because it proved useful as a giant radio antenna.", q: "What helped save the Eiffel Tower from being demolished after 20 years?", options: ["It was useful for radio","Its iron was too costly to remove","A public vote in 1909","A special wartime law"], a: 0, explain: "Many artists signed a petition against it in 1887, calling it a useless and monstrous tower.", tip: "" },
  { id: "hi26", topic: "history", headline: "The 1918 'Spanish flu' probably didn't start in Spain", body: "During World War I, warring nations censored news of the disease to protect morale. Neutral Spain reported freely, including on its king's illness, so it looked as if Spain was hit hardest.", q: "Why did the 1918 influenza pandemic get the name 'Spanish flu'?", options: ["It was first detected in Madrid","Spain's uncensored press reported it","Spanish troops carried it across Europe","A Spanish doctor first identified it"], a: 1, explain: "The pandemic infected around a third of the world's population and killed tens of millions of people.", tip: "" },
  { id: "hi27", topic: "history", legendary: true, headline: "Vikings were felling trees in Canada in exactly 1021", body: "At L'Anse aux Meadows in Newfoundland, Viking wood shows cuts from metal tools. A 2021 study dated them to 1021 using a burst of cosmic radiation in 993 recorded in tree rings, 471 years before Columbus.", q: "In what year were Vikings shown to be cutting wood in Newfoundland, Canada?", options: ["986","1021","1066","1492"], a: 1, explain: "The trick: a solar storm in 993 left a radiocarbon spike in tree rings worldwide, letting scientists count years from it.", tip: "" },
  { id: "hi28", topic: "history", headline: "In the 1800s, New England ice was shipped all the way to India", body: "Boston merchant Frederic Tudor built a business cutting winter ice from ponds and shipping it in sawdust-packed holds. In 1833 a shipment sailed about four months to Calcutta, and much of it survived.", q: "What did Frederic Tudor, the 'Ice King', ship from New England to India?", options: ["Maple syrup","Cotton","Whale oil","Pond ice"], a: 3, explain: "Henry David Thoreau watched ice being cut at Walden Pond and wrote that it might end up in India.", tip: "" },
  // ---------------- MONEY ----------------
  { id: "mo19", topic: "money", headline: "China used paper money about 600 years before Europe", body: "In the early 1000s, merchants in Sichuan, China, began issuing paper notes called jiaozi to replace heavy iron coins, and the government soon took over. Europe's first banknotes came in Sweden in 1661.", q: "Where did government-issued paper money first appear?", options: ["China","Greece","Venice","England"], a: 0, explain: "Marco Polo later described with amazement how Kublai Khan's empire ran on paper money.", tip: "" },
  { id: "mo20", topic: "money", headline: "On Yap, giant stone money changes owners without moving", body: "On the Pacific island of Yap, huge carved limestone discs called rai, some taller than a person, serve as money for important exchanges. Ownership is tracked by community memory, so the stones stay put.", q: "How does ownership of Yap's giant stone money usually change hands?", options: ["By rolling it to the new owner's home","By agreement; the stone stays put","By carving the new owner's name on it","By breaking off a piece to pay"], a: 1, explain: "The stones were quarried on Palau, hundreds of kilometres away, and brought back by canoe and raft.", tip: "" },
  { id: "mo21", topic: "money", headline: "Paying the highest-interest debt first saves the most money", body: "The 'avalanche' method means paying minimums on every debt, then putting all extra money toward the one with the highest interest rate. Mathematically, it minimises the total interest you pay.", q: "Which debt should extra payments go to first to minimise total interest?", options: ["The one with the smallest balance","The most recently opened one","The one with the highest rate","The one with the largest balance"], a: 2, explain: "The 'snowball' method, paying the smallest balance first, usually costs more, but some find its quick wins motivating.", tip: "List your debts by interest rate. Pay the minimum on all of them and put every spare pound or dollar on the top one." },
  { id: "mo22", topic: "money", headline: "Investing a fixed sum regularly buys more shares when prices fall", body: "With dollar-cost averaging, the same amount buys more shares when prices are low and fewer when high. As a result, your average cost per share ends up at or below the average price over that time.", q: "If you invest a fixed sum every month, how does your average cost per share compare?", options: ["Higher than the average price","Always equal to the latest price","Below the lowest price you paid","At or below the average price"], a: 3, explain: "If you already have a lump sum, investing it all at once has historically come out ahead more often than not.", tip: "Automate a fixed monthly investment so you buy steadily through ups and downs without having to decide each time." },
  { id: "mo23", topic: "money", legendary: true, headline: "Isaac Newton spent his later years hunting counterfeiters", body: "In 1696 Isaac Newton became Warden of the Royal Mint. He tracked down forgers himself, questioning suspects and witnesses, and helped convict the notorious counterfeiter William Chaloner, hanged in 1699.", q: "What job did Isaac Newton take on later in life that involved catching criminals?", options: ["Running the Royal Mint","Chief of the London police","Royal tax collector","Judge at the Old Bailey"], a: 0, explain: "Coins with ridged edges made 'clipping' off precious metal obvious, and Newton oversaw a huge recoinage.", tip: "" },
  { id: "mo24", topic: "money", headline: "The first coins were made about 2,600 years ago in Lydia", body: "The kingdom of Lydia, in what is now western Turkey, struck the first known coins in the 600s BCE from electrum, a natural mix of gold and silver, stamped with designs like a lion's head.", q: "Where were the world's first known coins minted?", options: ["Ancient Egypt, along the Nile","Lydia, in modern-day Turkey","Mesopotamia, in modern-day Iraq","Ancient Rome, under the Republic"], a: 1, explain: "Lydia's later king Croesus was so wealthy that 'rich as Croesus' is still a saying today.", tip: "" },
  { id: "mo25", topic: "money", headline: "Monopoly began as a game warning about the dangers of monopolies", body: "In 1904 Lizzie Magie patented 'The Landlord's Game' to show how landlords grow rich while tenants struggle. Versions spread for decades before Parker Brothers sold Monopoly in 1935.", q: "Why did Lizzie Magie create the game that became Monopoly?", options: ["To teach children to count money","To promote real estate sales","To show the harms of monopolies","To raise funds for a charity"], a: 2, explain: "Magie's game included two sets of rules, including one in which all players were rewarded when wealth was created.", tip: "" },
  { id: "mo26", topic: "money", headline: "Most money isn't cash: banks create it when they make loans", body: "In modern economies, the vast majority of money exists as bank deposits, not notes and coins. The Bank of England has explained that when a bank lends, it creates a new deposit for the borrower.", q: "In modern economies, what form does most money take?", options: ["Paper banknotes","Coins","Gold reserves","Bank deposits"], a: 3, explain: "The Bank of England laid this out in a widely read 2014 paper, 'Money creation in the modern economy'.", tip: "" },
  { id: "mo27", topic: "money", headline: "The US stopped making pennies because each cost almost 4 cents", body: "In fiscal 2024 the US Mint spent about 3.7 cents to make and ship each 1-cent coin, which is mostly zinc with a thin copper coat. The Treasury ordered production halted, and the last circulating penny was struck in November 2025.", q: "Why did the US Mint stop making pennies for circulation in 2025?", options: ["Each cost more than a cent to make","A shortage of copper for the coins","A law banned coins under 5 cents","Shops refused to accept them"], a: 0, explain: "Existing pennies are still legal tender; some shops now round cash totals to the nearest 5 cents.", tip: "" },
  { id: "mo28", topic: "money", headline: "US dollar bills are made of cotton and linen, not paper", body: "US banknotes are printed on a blend of 75% cotton and 25% linen, with red and blue security fibres woven in. That's why a bill can survive a trip through the washing machine.", q: "What are US dollar bills mainly made of?", options: ["Wood-pulp paper","Cotton and linen","Plastic polymer film","Silk and paper"], a: 1, explain: "Many countries, such as Canada, the UK and Australia, have switched to plastic polymer notes instead.", tip: "Damaged US banknotes can be sent to the Bureau of Engraving and Printing, which may replace them for free." },
  // ---------------- MIND ----------------
  { id: "mi19", topic: "mind", headline: "Naming the ink colour of a colour word is surprisingly hard", body: "When the word RED is printed in blue ink, people are slower and make more mistakes saying 'blue'. Reading is so automatic that it interferes. This is the Stroop effect, first published in 1935.", q: "In the Stroop effect, what slows people down?", options: ["Reading words in very dim light","Words printed upside down on cards","A colour word in a clashing ink","Words with unusually many letters"], a: 2, explain: "It's one of the most replicated results in psychology and is used to study attention and self-control.", tip: "" },
  { id: "mi20", topic: "mind", legendary: true, headline: "What you see can change what you hear", body: "Watch a video of someone mouthing 'ga' dubbed with the sound 'ba', and many people hear 'da'. Your brain merges sight and sound into one perception. This is the McGurk effect, reported in 1976.", q: "In the McGurk effect, what changes the sound people think they hear?", options: ["The speaker's regional accent","The loudness of the speech","Music playing in the background","The speaker's lip movements"], a: 3, explain: "Close your eyes and you hear the real 'ba' again; open them and the illusion returns.", tip: "" },
  { id: "mi21", topic: "mind", headline: "We remember the start and end of a list best, and the middle worst", body: "In a list of words, people recall the first items (the primacy effect) and the last items (the recency effect) best. The middle tends to get lost. This serial position effect is long established.", q: "Which items in a list are people least likely to remember?", options: ["The ones in the middle","The very first ones","The ones at the very end","The shortest words on it"], a: 0, explain: "In a classic 1966 study, a short distracting delay before recall wiped out the recency boost but not primacy.", tip: "When learning a list, give extra practice to the middle items, or shuffle the order between study sessions." },
  { id: "mi22", topic: "mind", headline: "Working memory holds only about four chunks at a time", body: "The famous 'seven plus or minus two' has been revised: modern research suggests we can hold only about four meaningful chunks in mind at once. Grouping items into chunks stretches that limit.", q: "About how many chunks of information can working memory hold at once?", options: ["About 1","About 4","About 12","About 20"], a: 1, explain: "Chess masters recall real game positions far better than novices; for random boards, the edge mostly vanishes.", tip: "Remember numbers in chunks: 0207 946 0123 sticks far better than 02079460123." },
  { id: "mi23", topic: "mind", headline: "Your own name can cut through a noisy room's chatter", body: "In experiments where people listened to one voice and ignored another, a fair share noticed when their own name was spoken in the ignored stream. It's called the cocktail party effect.", q: "What is the 'cocktail party effect'?", options: ["Talking louder after a drink or two","Forgetting names at parties","Focusing on one voice in a crowd","Mimicking others' accents"], a: 2, explain: "Research in the 1990s found about a third of people noticed their name in the ignored stream.", tip: "" },
  { id: "mi24", topic: "mind", headline: "The Müller-Lyer illusion fools you even after you've measured it", body: "Two equal lines, one with arrowheads pointing out and one with them pointing in, look different lengths. Even after measuring them and knowing the truth, most people still see them as unequal.", q: "What happens to the Müller-Lyer illusion once you know the lines are equal?", options: ["It disappears for good","The lines swap lengths","It turns into a 3D shape","It still looks unequal"], a: 3, explain: "German psychiatrist Franz Carl Müller-Lyer published the illusion in 1889.", tip: "" },
  { id: "mi25", topic: "mind", headline: "Your brain can be tricked into feeling a rubber hand is yours", body: "Hide your real hand and watch a rubber hand being stroked in sync with it. Within minutes, many people feel the rubber hand belongs to them. It was first reported in 1998.", q: "In the rubber hand illusion, what makes people feel a fake hand is theirs?", options: ["Strokes seen and felt in sync","Being hypnotised beforehand","Staring at it for several minutes","Wearing a glove that matches it"], a: 0, explain: "When the rubber hand is threatened, people's skin shows a stress response as if their real hand were at risk.", tip: "" },
  { id: "mi26", topic: "mind", headline: "Repeat a word enough and it stops meaning anything", body: "Say a word like 'spoon' over and over for half a minute and it starts to sound like a strange noise. This temporary loss of meaning is called semantic satiation, a term coined in 1962.", q: "What is the odd mental effect known as 'semantic satiation'?", options: ["Feeling mentally full after reading","A word losing meaning when repeated","Remembering a word for a lifetime","Mixing up two similar-sounding words"], a: 1, explain: "The likely cause is that the brain's response to the word weakens with each rapid repetition.", tip: "" },
  { id: "mi27", topic: "mind", headline: "On the tip of your tongue, you often know a word's first letter", body: "In the 'tip of the tongue' state, you can't retrieve a word but can often recall its first letter or number of syllables. A classic 1966 study showed this partial knowledge is real.", q: "In a 'tip of the tongue' moment, what can people often still recall?", options: ["The word's exact spelling","Nothing at all about the word","The word's first letter","Its meaning in another language"], a: 2, explain: "These moments become more frequent with age, and they're especially common for people's names.", tip: "" },
  { id: "mi28", topic: "mind", headline: "Many people miss it when the stranger they're talking to is swapped", body: "In a small 1998 field study, a researcher asked passers-by for directions. Mid-chat, two men carrying a door walked between them and the researcher was swapped for someone else. About half of people didn't notice.", q: "In a 1998 study, a stranger asking for directions was secretly swapped mid-chat. What happened?", options: ["Nearly everyone noticed at once","About half didn't notice the swap","Not a single person noticed","People only noticed after leaving"], a: 1, explain: "It's an example of change blindness: we hold far less visual detail in mind than it feels like we do.", tip: "" },
  // ---------------- TECH ----------------
  { id: "te19", topic: "tech", headline: "Bubble wrap was first invented as a textured wallpaper", body: "In 1957 two engineers in New Jersey sealed two plastic shower curtains together, trapping air bubbles, hoping to sell it as wallpaper. It flopped, and so did greenhouse insulation, before it found a role in packaging.", q: "What was bubble wrap originally invented to be?", options: ["Textured wallpaper","Packing material","Swimming-pool cover","Medical bandages"], a: 0, explain: "One of its first big packaging clients was IBM, shipping its new 1401 computer.", tip: "" },
  { id: "te20", topic: "tech", headline: "The first computer mouse was a wooden box with two wheels", body: "Douglas Engelbart's team at SRI built the first mouse in 1964: a carved wooden shell with two metal wheels set at right angles to track movement. It was shown to the world in a famous 1968 demo.", q: "What was the first computer mouse's shell made of?", options: ["Steel","Wood","Plastic","Glass"], a: 1, explain: "It got its name because the cord trailing from the back looked like a tail.", tip: "" },
  { id: "te21", topic: "tech", headline: "Wi-Fi doesn't stand for 'wireless fidelity'", body: "'Wi-Fi' is a brand name created in 1999 by the marketing firm Interbrand, chosen because it sounded catchy, a little like 'hi-fi'. The 'wireless fidelity' phrase was added later and means nothing.", q: "What does the name 'Wi-Fi' actually stand for?", options: ["Wireless fidelity, like hi-fi","Wide frequency networking","Nothing: it's a brand name","Wireless file interface"], a: 2, explain: "The technical name for the standard is IEEE 802.11, which marketers felt nobody would remember.", tip: "" },
  { id: "te22", topic: "tech", headline: "The first text message, sent in 1992, said 'Merry Christmas'", body: "On 3 December 1992, engineer Neil Papworth typed 'Merry Christmas' on a computer and sent it to a colleague's mobile phone on the Vodafone network in the UK.", q: "What did the first SMS text message, sent in 1992, say?", options: ["Hello world","Can you hear me?","Testing 1, 2, 3","Merry Christmas"], a: 3, explain: "The recipient, Richard Jarvis, couldn't reply, because phones of the time couldn't send texts.", tip: "" },
  { id: "te23", topic: "tech", legendary: true, headline: "The internet's first message was 'LO', because it crashed", body: "On 29 October 1969, a UCLA student tried to log in to a computer at Stanford Research Institute over ARPANET. He typed 'L', then 'O', and the system crashed before 'G'. 'LO' was the first message.", q: "What was the first message ever sent over ARPANET, the internet's ancestor?", options: ["LO","HELLO","LOGIN","TEST"], a: 0, explain: "About an hour later, they got the system running again and completed the full login.", tip: "" },
  { id: "te24", topic: "tech", headline: "Passkeys can't be phished the way passwords can", body: "A passkey uses a pair of cryptographic keys; the secret one never leaves your device. It's tied to the real website's address, so a lookalike scam site can't trick you into handing it over.", q: "Why are passkeys resistant to phishing?", options: ["They change every few seconds","They only work on the real site","They are very long passwords","They're stored only by your bank"], a: 1, explain: "Passkeys are built on the FIDO2 standard, supported by major operating systems and browsers.", tip: "Turn on passkeys or an authenticator app where you can; codes sent by text message are the weakest option." },
  { id: "te25", topic: "tech", headline: "The World Wide Web was invented at a physics lab", body: "In 1989 Tim Berners-Lee, a British scientist at CERN near Geneva, proposed a system of linked documents to help researchers share information. The first website went live there in 1991, and a restored copy is still online.", q: "Where was the World Wide Web invented?", options: ["CERN, a physics lab near Geneva","Bell Labs in New Jersey","Xerox PARC in California","MIT in Massachusetts"], a: 0, explain: "The web runs on the internet but isn't the same thing: the internet grew from ARPANET, two decades earlier.", tip: "You can still visit the restored first website at info.cern.ch." },
  { id: "te26", topic: "tech", headline: "Microwave ovens use nearly the same frequency as Wi-Fi", body: "Most microwave ovens run at about 2.45 GHz, right in the 2.4 GHz band used by many Wi-Fi networks. Their shielding blocks most of it, but enough can leak to slow a nearby connection.", q: "Why can a running microwave oven slow down nearby Wi-Fi?", options: ["It drains the router's power","Its light blocks the signal","It heats up the router","Both use about 2.4 GHz"], a: 3, explain: "That frequency isn't special for water; it was chosen partly because it was set aside for non-communication uses.", tip: "If video calls stutter while the microwave runs, switch your device to your router's 5 GHz network." },
  { id: "te27", topic: "tech", headline: "Every colour on your screen is mixed from red, green and blue dots", body: "Each pixel is made of tiny red, green and blue subpixels. By varying their brightness, screens fool your eyes into seeing millions of colours. A drop of water on the screen acts as a lens to reveal them.", q: "Which three colours of light do screens mix to make every other colour?", options: ["Red, green and blue","Red, yellow and blue","Cyan, magenta and yellow","Black, white and grey"], a: 0, explain: "Yellow on a screen is just red and green subpixels lit together; there's no yellow light at all.", tip: "" },
  { id: "te28", topic: "tech", headline: "Punched cards for weaving silk helped inspire the computer", body: "Jacquard's loom of 1804 used chains of punched cards to control its woven patterns. Charles Babbage planned to feed instructions to his Analytical Engine with punched cards.", q: "What machine's punched cards inspired Charles Babbage's computer designs?", options: ["Gutenberg's printing press","Jacquard's weaving loom","Morse's electric telegraph","The steam locomotive"], a: 1, explain: "Ada Lovelace wrote that the Engine 'weaves algebraical patterns just as the Jacquard loom weaves flowers and leaves'.", tip: "" },
  // ---------------- CULTURE ----------------
  { id: "cu19", topic: "culture", headline: "Ancient Greek statues were brightly painted, not plain white", body: "Traces of pigment show that many ancient Greek and Roman statues and temples were painted in vivid colours. Most of the paint wore away over centuries, leaving the bare marble we picture today.", q: "How did many ancient Greek statues originally look?", options: ["Pure white marble","Covered in gold leaf","Brightly painted","Dark bronze only"], a: 2, explain: "Researchers use UV light and chemical analysis to detect faded pigments and reconstruct the original colours.", tip: "" },
  { id: "cu20", topic: "culture", headline: "The Statue of Liberty was originally copper-brown", body: "The statue's copper skin was shiny brown when it was unveiled in 1886. Exposure to air and water slowly formed a green patina, which had covered it by about 1920.", q: "What colour was the Statue of Liberty when it was unveiled in 1886?", options: ["Green, as it is today","Gleaming white","Gilded gold all over","Shiny copper-brown"], a: 3, explain: "The patina protects the copper beneath it, so it was left in place rather than cleaned off.", tip: "" },
  { id: "cu21", topic: "culture", headline: "Nintendo was founded in 1889 to make playing cards", body: "Nintendo began in Kyoto, Japan, making hanafuda, traditional flower-patterned playing cards. It tried ventures from taxis to instant rice before finding success with toys and video games.", q: "What did Nintendo originally make when it was founded in 1889?", options: ["Playing cards","Paper lanterns","Sewing machines","Bicycles"], a: 0, explain: "Nintendo still makes hanafuda cards in Japan today.", tip: "" },
  { id: "cu22", topic: "culture", headline: "'OK' began as a joke abbreviation for 'oll korrect'", body: "In 1830s Boston, newspapers had a fad for jokey misspelled abbreviations. 'O.K.' for 'oll korrect' appeared in print in 1839 and was later boosted by Martin Van Buren's 1840 campaign.", q: "What did 'O.K.' originally abbreviate in 1839?", options: ["A telegraph operators' code","'Oll korrect', a joke spelling","A Greek phrase meaning 'all good'","A Choctaw word meaning 'it is so'"], a: 1, explain: "Van Buren was nicknamed 'Old Kinderhook' after his hometown, and his supporters formed 'O.K. Clubs'.", tip: "" },
  { id: "cu23", topic: "culture", headline: "The croissant has Austrian roots", body: "The croissant descends from the Austrian kipferl, a crescent-shaped roll. It took off in Paris after an Austrian bakery opened there in the 1830s, and the flaky, buttery version was perfected by French bakers.", q: "Which earlier pastry is the croissant descended from?", options: ["The Italian cannoli","The Greek baklava","The Austrian kipferl","The Danish kringle"], a: 2, explain: "Pastries made in this style, from buttery laminated dough, are still called 'viennoiserie' in French.", tip: "" },
  { id: "cu24", topic: "culture", headline: "The Hollywood sign originally read 'Hollywoodland'", body: "The sign went up in 1923 to advertise a new housing development called Hollywoodland. In 1949 the last four letters were removed, and it became a symbol of the film industry.", q: "What was the Hollywood sign originally built to advertise?", options: ["A new Hollywood film studio","A planned theme park","A local radio station","A housing development"], a: 3, explain: "Each of the original letters was about 15 metres tall, and the sign was lit with thousands of bulbs.", tip: "" },
  { id: "cu25", topic: "culture", headline: "Japanese haiku count sound units, not syllables", body: "Haiku's 5-7-5 pattern counts 'on', Japanese sound units that are shorter than many English syllables. So many English-language haiku poets write shorter poems than 17 syllables to match the feel.", q: "What does a traditional Japanese haiku's 5-7-5 pattern count?", options: ["Sound units called 'on'","English-style syllables","Words in each line","Stressed beats per line"], a: 0, explain: "Traditional haiku also include a 'kigo', a word that hints at the season.", tip: "Try writing one about your day: three short lines, a hint of the season, and a moment that shifts." },
  { id: "cu26", topic: "culture", legendary: true, headline: "The chess queen could once move just one square diagonally", body: "In older forms of chess, the queen's ancestor, the fers or counsellor, moved only one square diagonally. Around the late 1400s in Europe it became the powerful queen we know.", q: "How did the queen's ancestor move in early versions of chess?", options: ["Any distance in any direction","One square diagonally","Like a knight","Two squares straight ahead"], a: 1, explain: "The faster game was nicknamed 'mad queen chess', and within decades it had replaced the slower version.", tip: "" },
  { id: "cu27", topic: "culture", headline: "Leonardo da Vinci filled his notebooks with mirror writing", body: "Leonardo, who was left-handed, wrote most of his notes from right to left with letters reversed. They are easiest to read in a mirror. Why he did it is unknown, though it may have avoided smudging ink.", q: "What was unusual about how Leonardo da Vinci wrote his notes?", options: ["He wrote only in code numbers","He wrote upside down","He wrote in mirror script","He left out all the vowels"], a: 2, explain: "Over 7,000 pages of his notebooks survive, filled with sketches of machines, anatomy and nature.", tip: "" },
  { id: "cu28", topic: "culture", headline: "Blue jeans got their rivets from a tailor's idea in 1873", body: "Tailor Jacob Davis began reinforcing work trousers with copper rivets so pockets wouldn't tear. He partnered with fabric supplier Levi Strauss, and they received a US patent in 1873.", q: "Why were copper rivets first added to work trousers in the 1870s?", options: ["As a fashionable decoration","To mark the maker's brand name","To hold up suspenders for miners","To stop pockets from tearing"], a: 3, explain: "The word 'denim' likely comes from 'serge de Nîmes', a fabric from the French city of Nîmes.", tip: "To keep jeans dark longer, wash them inside out in cold water, and less often." }
);
